{"CommandLine":"python -c "from app import app, db; from models import Facility, Emission, ProductionData, CapEmission, Scope2Emission, FlaringDetail;
with app.app_context():
    for fid in [4, 13, 14, 169, 170]:
        f = Facility.query.get(fid)
        print(f'=== FACILITY {fid}: {f.name} ({f.code}) ===')
        ems = Emission.query.filter_by(facility_id=fid).all()
        by_year = {}
        for e in ems:
            by_year.setdefault(e.year, []).append(e)
        for y, elist in sorted(by_year.items()):
            tot_co2e = sum(e.co2e_total or 0 for e in elist)
            tot_ch4 = sum(e.ch4_emissions or 0 for e in elist)
            ptypes = set(e.process_type for e in elist)
            print(f'Year {y}: {len(elist)} recs, CO2e={tot_co2e:,.1f}, CH4={tot_ch4:,.1f}, types={ptypes}')
        prods = ProductionData.query.filter_by(facility_id=fid).all()
        pby_year = {}
        for p in prods:
            pby_year.setdefault(p.year, []).append(p)
        for y, plist in sorted(pby_year.items()):
            tot_boe = sum(p.total_production_mmboe or 0 for p in plist)
            tot_gas = sum(p.gross_gas_mmsm3 or p.gas_amount or 0 for p in plist)
            print(f'Prod Year {y}: {len(plist)} entries, Gas={tot_gas:,.1f}, BOE={tot_boe:,.1f}')
